-- 순서가 중요하다

@Test
@Transactional
void 목록_먼저() {
    em.clear();
    long n = counter.count(() -> {
        memberRepository.findAll();
        for (long id = 1; id <= 3; id++) memberRepository.findById(id);
    });
    System.out.println("목록 먼저: 쿼리 " + n + "개");
}

목록 먼저: 쿼리 1개

@Test
@Transactional
void 단건_먼저() {
    em.clear();
    long n = counter.count(() -> {
        for (long id = 1; id <= 3; id++) memberRepository.findById(id);
        memberRepository.findAll();
    });
    System.out.println("단건 먼저: 쿼리 " + n + "개");
}

단건 먼저: 쿼리 4개

--   순서만 바꿨는데 1개와 4개다
--   목록이 캐시를 채워 둔다


-- 그런데 findAll 은 캐시를 덮지 않는다

@Test
@Transactional
void 캐시_우선() {
    Member m = memberRepository.findById(1L).orElseThrow();
    m.changeAge(999);

    System.out.println("--- findAll ---");
    List<Member> all = memberRepository.findAll();
    Member same = all.stream()
            .filter(x -> x.getId().equals(1L)).findFirst().orElseThrow();
    System.out.println("나이: " + same.getAge());
    System.out.println("같은 객체: " + (m == same));
}

